contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 amount) public payable {
        uint256 beforeTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeTargetBalance = c.balanceOf(target); if (__ESBMC_reverted()) return;

        bool reverted;
        c.mintToken(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterTargetBalance = c.balanceOf(target); if (__ESBMC_reverted()) return;

        assert(!reverted && afterTotalSupply == beforeTotalSupply + amount && afterTargetBalance == beforeTargetBalance + amount);
    }

    receive() external payable {}
}

